//首页轮播
var indexImgPlay = function() {
    $box = $(".index-img");
    $ul = $box.find(".img-box");
    $li = $ul.find(".ul").find("li");
    $left = $box.find("a.left");
    $right = $box.find("a.right");
    $ani = $box.find("div.width");
    $i = $li.length;
    $w = $ul.find("img").width();
    $cur = 1;
    $time = 1500;
    $movTime = 3e3;
    $li.eq(0).show();
    var e;
    $right.click(function() {
        if (!$li.is(":animated")) {
            $cur < $i && $li.eq($cur).fadeIn($time,
            function() {
                $cur++
            }).siblings().fadeOut($time);
            $cur == $i && $li.eq(0).fadeIn($time,
            function() {
                $cur = 1
            }).siblings().fadeOut($time)
        }
    });
    $left.click(function() {
        if (!$li.is(":animated")) {
            $cur > 1 && $li.eq($cur - 2).fadeIn($time,
            function() {
                $cur--
            }).siblings().fadeOut($time);
            $cur == 1 && $li.eq($i - 1).fadeIn($time,
            function() {
                $cur = $i
            }).siblings().fadeOut($time)
        }
    });
    $(".is-me").hover(function() {
        if (!$left.is(":animated")) {
            $left.animate({
                left: 0,
                opacity: 1
            },
            300);
            $right.animate({
                right: 0,
                opacity: 1
            },
            300)
        }
    },
    function() {
        if (!$left.is(":animated")) {
            $left.animate({
                left: "-85px",
                opacity: 0
            },
            300);
            $right.animate({
                right: "-85px",
                opacity: 0
            },
            300)
        }
    });
    $box.live("mouseenter",
    function() {
        clearInterval(e)
    }).live("mouseleave",
    function() {
        e = setInterval(function() {
            $right.trigger("click")
        },
        $movTime)
    }).trigger("mouseleave")
}; (function(e) {
    e.fn.extend({
        LazyLoad: function(t) {
            function o() {
                r.each(function(t) {
                    var o = r.eq(t).attr("img-data"),
                    u = r.eq(t).offset();
                    if (u.top + i >= e(window).scrollTop() && e(window).scrollTop() + n >= u.top + i) {
                        r.eq(t).attr("src") == s && r.eq(t).hide();
                        r.eq(t).attr("src",
                        function() {
                            return o
                        }).fadeIn(300)
                    }
                })
            }
            var n = e(window).height() + 100,
            r = this,
            i = parseInt(r.height() / 2),
            s = "";
            o();
            e(window).scroll(function() {
                o()
            })
        }
    })
})(jQuery); (function(e) {
    e.fn.popDiv = function(t) {
        var n = {
            goal: this,
            btn: ".ui-btn",
            text: "文本"
        },
        r = e.extend(n, t),
        i = document.documentElement.clientWidth / 2,
        s = document.documentElement.scrollTop || document.body.scrollTop,
        o = document.documentElement.clientHeight / 2 + s,
        u = document.body.scrollHeight;
        $h = e(r.goal).height() / 2;
        var a = this.width() / 2,
        f = this.height() / 2,
        l = '<div class="ui-popup" style="top:' + (o - f) + "px; left:" + (i - a) + 'px">' + '<div class="ui-popup-con"><a class="close" href="javascript:;">关闭</a>' + r.goal.clone().wrap("<div></div>").parent().remove().html() + "</div>" + "</div>" + '<div class="ui-mask" style="height:' + u + '" ></div>';
        $removeWrap = function() {
            e(".ui-mask,.ui-popup").fadeOut(300,
            function() {
                e(this).remove()
            })
        };
        e("body").append(l);
        e(".ui-popup").find(r.goal.selector).show();
        e(".ui-mask").fadeIn(300);
        e("body").keydown(function() {
            event.keyCode == 27 && $removeWrap()
        });
        e(r.btn).click(function() {
            $removeWrap()
        })
    }
})(jQuery);
$(function() {
    indexImgPlay();
    message();
    $(".lazy_img img").LazyLoad();
    $(".sort_menu").hover(function() {
        $(this).addClass("case_menu_on");
        $ul = $(this).find("ul");
        $ul.is(":animated") || $ul.css({
            display: "block"
        }).animate({
            opacity: "1"
        },
        300)
    },
    function() {
        $(this).removeClass("case_menu_on");
        $ul = $(this).find("ul");
        $ul.is(":animated") || $ul.animate({
            height: "0",
            opacity: "0"
        },
        300,
        function() {
            $ul.css({
                height: "auto",
                display: "none"
            })
        })
    });
    $(".case-li").hover(function() {
        if (!$(this).find("*").is(":animated")) {
            $(this).addClass("case-li-hover");
            $(this).find(".link").animate({
                opacity: ".2"
            },
            300);
            $(this).find(".category").animate({
                bottom: "40px",
                opacity: "1"
            },
            300);
            $(this).find(".show").animate({
                top: "30px",
                opacity: "1"
            },
            300)
        }
    },
    function() {
        $(this).find(".link").animate({
            opacity: "1"
        },
        300,
        function() {
            $(this).removeClass("case-li-hover")
        });
        $(this).find(".category").animate({
            bottom: "20px",
            opacity: 0
        },
        300);
        $(this).find(".show").animate({
            top: "-30px",
            opacity: "0"
        },
        300)
    });
    $("#caseVideo .case-content").live("click",
    function() {
        if ($("body").hasClass("caseVideoMask")) $(".caseVideoMask .ui-mask").fadeOut(300,
        function() {
            $(this).remove();
            $("body").removeClass("caseVideoMask")
        });
        else {
            $("#caseVideo").append('<div class="ui-mask"></div>');
            $(".case-page .ui-mask").fadeIn(300);
            $("body").addClass("caseVideoMask")
        }
    });
    $(".caseVideoMask .ui-mask").live("click",
    function() {
        $(this).fadeOut(300,
        function() {
            $(this).remove();
            $("body").removeClass("caseVideoMask")
        })
    })
});
var message = function() {
    $(".post_form .text").each(function() {
        $(this).val(this.defaultValue)
    });
    $(".message .text").focus(function() {
        $(this).val() == this.defaultValue && $(this).val("").css("color", "#333")
    }).blur(function() {
        $(this).val() == "" && $(this).val(this.defaultValue).css("color", "#eee")
    });
    $(".contact .message .form button").click(function() {
        $len = $(".post_form .text").length - 1;
        $(".post_form .text").each(function() {
            $n = $(".contact .message .form .text").index(this);
            if ($n == $len) $("form").submit();
            else if ($(this).val() == this.defaultValue) {
                var e = $(this).attr("title");
                $(this).animate({
                    backgroundColor: "#e9f091",
                    color: "#ff4800"
                },
                200).animate({
                    backgroundColor: "#fff",
                    color: "#eee"
                },
                350);
                $x = $(this).offset().top;
                $("html,body").animate({
                    scrollTop: $x - 10
                },
                300);
                return ! 1
            }
        });
        return ! 1
    })
};